<style>
.contract-hero{display:grid;grid-template-columns:minmax(0,1fr) 220px;gap:22px;padding:28px;border-radius:24px;background:linear-gradient(135deg,#111827,#273449);color:#fff;margin-bottom:20px}.contract-hero h2{font-size:clamp(1.7rem,3vw,2.7rem);margin:.25rem 0}.contract-value{display:flex;flex-direction:column;justify-content:center;padding:20px;border:1px solid #ffffff2b;border-radius:18px;background:#ffffff12}.contract-value strong{font-size:2rem}.contract-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,.8fr);gap:20px}.contract-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 20px}.contract-metric,.contract-card{background:#fff;border:1px solid var(--border-color,#dfe4ea);border-radius:18px;padding:18px}.contract-metric span,.contract-card>span{display:block;color:#64748b;font-size:.78rem;text-transform:uppercase;letter-spacing:.08em}.contract-metric strong{display:block;font-size:1.45rem;margin:.25rem 0}.contract-record{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;padding:14px 0;border-bottom:1px solid #e5e7eb}.contract-record:last-child{border-bottom:0}.contract-record small{display:block;color:#64748b;margin-top:4px}.contract-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}.contract-kpis div{padding:10px;border-radius:12px;background:#f8fafc}.contract-kpis span,.contract-kpis strong{display:block}.contract-history a{display:block;padding:12px;border:1px solid #e5e7eb;border-radius:12px;margin-top:10px}.contract-history a.active{border-color:#111827;background:#f8fafc}.contract-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.contract-form .span-2{grid-column:1/-1}.contract-form label span{display:block;font-weight:700;margin-bottom:6px}.contract-form input,.contract-form select,.contract-form textarea{width:100%}.contract-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.contract-timeline{border-left:2px solid #dbe3ee;padding-left:18px}.contract-event{position:relative;padding:0 0 16px}.contract-event:before{content:"";position:absolute;width:10px;height:10px;border-radius:50%;background:#334155;left:-24px;top:6px}@media(max-width:1000px){.contract-layout,.contract-hero{grid-template-columns:1fr}.contract-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.contract-metrics,.contract-form,.contract-kpis{grid-template-columns:1fr}.contract-form .span-2{grid-column:auto}}
</style>